package com.fitlife.usuario.controller;
import com.fitlife.usuario.service.UsuarioService;import java.util.Map;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/usuarios") public class UsuarioController{private final UsuarioService service;public UsuarioController(UsuarioService s){service=s;}@PostMapping("/cadastro")public ResponseEntity<Map<String,Object>> cadastrar(@RequestBody Map<String,Object>d){return ResponseEntity.status(HttpStatus.CREATED).body(service.cadastrar(d));}@PostMapping("/login")public Map<String,Object> login(@RequestBody Map<String,Object>d){return service.login(d);}@GetMapping("/{id}")public Map<String,Object> buscar(@PathVariable long id){return service.buscar(id);}@PutMapping("/{id}")public Map<String,Object> atualizar(@PathVariable long id,@RequestBody Map<String,Object>d){return service.atualizar(id,d);}@PutMapping("/{id}/informacoes-medicas")public Map<String,Object> medico(@PathVariable long id,@RequestBody Map<String,Object>d){return service.atualizarMedico(id,d);}@PutMapping(value="/{id}/foto",consumes="multipart/form-data")public Map<String,Object> foto(@PathVariable long id,@RequestPart("foto")MultipartFile f)throws java.io.IOException{return service.foto(id,f);}}
